-- D GlacierPoint: declined
update fs_grant_deadlines set status='declined', amount_awarded=0, decision_on='2026-11-03', next_step_due=null, updated_at=now(),
 next_step=$q$DECLINED Nov 3, 2026 (Vinnie Bahl, Business Development Manager, GlacierPoint Great Lakes Division, reply to our Nov 2 contact form): Great Lakes does not handle events like this, its minimum paid order is 15 cases, and it does not loan freezers. No donation, discount or freezer loan. Closed; do not resubmit the form or visit. Remaining routes: Prairie Farms (waiting on the Nov 1 email), Instantwhip, and the Good Humor and Dreyer's forms.$q$,
 notes=replace(coalesce(notes,''),'RANK 1 (distributor).','RANK 1 (distributor; DECLINED Nov 3, 2026, see end of notes).')||chr(10)||$q$2026-11-03 DECLINED (decision of record): Vinnie Bahl, Business Development Manager, Great Lakes Division, Tue Nov 3 2026 14:27:48 UTC = 8:27 am CST, Message-ID <DS2PR18MB927617DC8EB105CF0A1CAA5C14B9692@DS2PR18MB927617.namprd18.prod.outlook.com>, to stephen@selassiefest.com, replying to the Nov 2 contact-form lead: "we do not handle events such as this and our minimum paid orders are 15 cases. We also do not loan out freezers for events." He added that it was kind of "our competition" (Fox Valley Farms) to refer us. Only paid orders of 15 or more cases are possible; no donation or discount was offered. [src:msgid-DS2PR18MB927617DC8EB105CF0A1CAA5C14B9692]$q$
where id='fc085d99-de80-478a-b0f9-cfdb3f58c519' and status='submitted' and next_step like 'Waiting on GlacierPoint reply to the Nov 2 contact form%' and coalesce(notes,'') not like '%[src:msgid-DS2PR18MB927617DC8EB105CF0A1CAA5C14B9692]%';

